  const match = /viewBox="[\d.-]+\s+[\d.-]+\s+([\d.]+)\s+([\d.]+)"/u.exec(svg);
  if (!match) return undefined;
  return [Number.parseFloat(match[1]), Number.parseFloat(match[2])];
}

