      product: "canvas",
      layout: "horizontal",
      colorMode: "color",
    }),
  };
  dialogConfig.onSubmit(api);

  const insertContent = (editor as unknown as { insertContent: (html: string) => void })
    .insertContent;
  expect(insertContent).toHaveBeenCalledWith(
